class PharmaciesProchesPage extends ConsumerWidget { const PharmaciesProchesPage({super.key}); @override Widget build(BuildContext c, WidgetRef r){ final list=[{'nom':'Pharmacie Gombe','dist':'0.3 km','open':true,'tel':'+243 81...'}, {'nom':'Pharmacie Victoire','dist':'0.9 km','open':true,'tel':'+243 82...'}, {'nom':'Pharmacie de Garde','dist':'1.2 km','open':true,'tel':'+243 99...'}]; return Scaffold(backgroundColor: ThixSanteColors.background, appBar: AppBar(title: const Text('Pharmacies proches', style: TextStyle(fontWeight: FontWeight.w800)), backgroundColor: Colors.white, leading: IconButton(icon: const Icon(Icons.arrow_back), onPressed: ()=>Navigator.pop(c))), body: ListView.builder(padding: const EdgeInsets.all(16), itemCount: list.length, itemBuilder: (_,i){final p=list[i]; return Card(child: ListTile(leading: const CircleAvatar(backgroundColor: ThixSanteColors.primarySurface, child: Icon(Icons.local_pharmacy, color: ThixSanteColors.primary)), title: Text(p['nom'] as String, style: const TextStyle(fontWeight: FontWeight.w800)), subtitle: Text('${p['dist']} • ${p['tel']}'), trailing: Container(padding: const EdgeInsets.symmetric(horizontal:8, vertical:4), decoration: BoxDecoration(color: ThixSanteColors.success.withOpacity(0.15), borderRadius: BorderRadius.circular(20)), child: const Text('Ouverte', style: TextStyle(color: ThixSanteColors.success, fontWeight: FontWeight.w700, fontSize:11))), onTap: (){}));})); } }
